{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "Cómo convertir imágenes con CovertConvert",
  "description": "Convierte HEIC, WebP, AVIF y otros formatos de imagen a JPG o PNG completamente en tu navegador.",
  "step": [
    {
      "@type": "HowToStep",
      "name": "Seleccionar archivos",
      "text": "Arrastra archivos de imagen al convertidor o haz clic para explorar. Soporta HEIC, WebP, AVIF, TIFF, PNG, BMP y GIF."
    },
    {
      "@type": "HowToStep",
      "name": "Elegir formato de salida",
      "text": "Selecciona JPEG para archivos más pequeños o PNG para calidad sin pérdida. Ajusta la calidad JPEG si lo deseas."
    },
    {
      "@type": "HowToStep",
      "name": "La conversión ocurre localmente",
      "text": "Tu navegador procesa las imágenes usando WebAssembly. Los archivos nunca salen de tu dispositivo."
    },
    {
      "@type": "HowToStep",
      "name": "Descargar resultados",
      "text": "Los archivos convertidos se descargan automáticamente. Múltiples archivos se agrupan en un archivo ZIP."
    }
  ]
}

